+++ b/training/level-1/L1-030-idempotency-key/idempotencyKey.mjs
@@ -0,0 +1,10 @@
+export function canonicalize(value) {
+  if (typeof value === "number" && !Number.isFinite(value)) throw new RangeError("number must be finite");
+  if (value === null || typeof value === "string" || typeof value === "boolean") {
+    return value;
+  }
+  if (typeof value === "number") {
+    return value;
+  }
+  return JSON.stringify(value);
+}

